def solution(input_str):
    # Read n and k
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Compute XOR sum of Grundy values for each pile
    xor_sum = 0

    for x in a:
        if k % 2 == 1:
            # For odd k: g(x) = 1 if x % 2 != 0 else 0
            if x % 2 == 1:
                xor_sum ^= 1
        else:
            # For even k: g(x) cycles with period 4: [0,1,2,1]
            cycle = [0, 1, 2, 1]
            xor_sum ^= cycle[x % 4]

    # If XOR sum != 0, first player (Kevin) wins; else second player (Nicky) wins
    if xor_sum != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

