def lcp(pre, suf):
    """Compute length of longest common prefix between pre and suf"""
    count = 0
    min_len = min(len(pre), len(suf))
    for i in range(min_len):
        if pre[i] == suf[i]:
            count += 1
        else:
            break
    return count

