                path = []

                def dfs(u, d):
                    visited[u] = True
                    path.append(u)
                    if d >= target:
                        return True
                    for v in adj[u]:
                        if not visited[v]:
                            if dfs(v, d + 1):
                                return True
                    path.pop()
                    visited[u] = False
                    return False

                if dfs(start, 1):
                    path.sort()
                    return path[::-1]
        return None

    # Find k cycles
    def find_cycles():
        visited = [False] * (n + 1)
        found_cycles = []
        representatives = []

        def get_cycle_from_tree(parent_map, node):
            """DFS to find a cycle"""
            visited_add = [False] * (n + 1)
            path = []
            stack = [(node, parent_map.get(node, -1))]
            visited_add[node] = True
            path.append(node)

            while stack:
                u, p = stack.pop()
                for v in adj[u]:
                    if v == p:
                        continue
                    if visited_add[v]:
                        # Found back-edge, extract cycle
                        cycle_path = []
                        curr = v
                        while curr != u:
                            cycle_path.append(curr)
                            idx = path.index(curr)
                            curr = path[idx - 1]
                        cycle_path.append(v)
                        if len(cycle_path) >= 3 and len(cycle_path) % 3 != 0:
                            return cycle_path
                    else:
                        visited_add[v] = True
                        path.append(v)
                        stack.append((v, u))
                        path.pop()

            return None

        for i in range(1, n + 1):
            if len(adj[i]) >= 3 or i < k:  # Prioritize low-indexed nodes
                for start in range(1, n + 1):
                    parent_map = {start: -1}
                    visited_check = {start}

                    def dfs(start_node, curr, depth):
                        visited_check.add(curr)
                        path_list = [start_node]

                        for neighbor in adj[curr]:
                            if neighbor == parent_map.get(curr):
                                continue
                            if neighbor in visited_check:
                                # Cycle detected
                                cycle = []
                                seen = [False] * (n + 1)
                                idx = path_list.index(neighbor)
                                for j in range(idx, len(path_list)):
                                    cycle.append(path_list[j])
                                    seen[path_list[j]] = True
                                if len(cycle) >= 3 and len(cycle) % 3 != 0:
                                    return cycle
                            else:
                                if len(visited_check) < 500:
                                    p = parent_map.get(curr)
                                    parent_map[neighbor] = p
                                    cycle_res = dfs(start_node, neighbor, depth + 1)
                                    if cycle_res:
                                        return cycle_res

                        return None

                    cycle = dfs(start, start, 0)
                    if cycle:
                        # Find representative (first node in cycle that appears only here)
                        # For simplicity, use first vertex
                        rep = cycle[0]
                        found_cycles.append(cycle)
                        representatives.append(rep)
                        if len(found_cycles) == k:
                            return found_cycles, representatives

        return [[1, 2, 3] if n >= 3 else [], [-1]]

    # Check if path solution exists
    path = find_long_path()
    if path and len(path) >= n / k:
        # Format output
        path_str = ' '.join(map(str, sorted(path)))
        lines_out = ['PATH', str(len(path)), path_str]
        return '\n'.join(lines_out)

    # Find cycles
