            if len(parts) >= 3:
                a, b, c = parts
                # Convert to 0-indexed, validate
                if 1 <= a <= n and 1 <= b <= n and c in [1, 2]:
                    adj[a - 1].append((b - 1, c))
                    adj[b - 1].append((a - 1, c))

    x = [0.0] * n
    visited = [False] * n

    def check_component(start):
        """
        BFS to explore component, assign values, and check consistency.
        If any inconsistency found (edge constraint violated), return False.
        """
