        visited[start] = True
        x[start] = 0.0  # Fix first node to 0 (relative value)

        while dq:
            u = dq.pop(0)  # BFS order
            val_u = x[u]

            for v, color in adj[u]:
                target = 1 if color == 1 else 2  # What x[u] + x[v] should equal

                if not visited[v]:
                    # Assign v relative to u
                    visited[v] = True
                    x[v] = target - val_u
                    dq.append(v)
                else:
                    # Check consistency
                    expected = target - val_u
                    if abs(x[v] - expected) > 1e-9:
                        return False

        return True

