class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = [s]
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] == -1:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] != -1

    def dfs(self, s, t, f, ptr):
        if f == 0 or s == t:
            return f
        ans = 0
        i = ptr[s]
        while i < len(self.graph[s]) and ans < f:
            v, cap, rev = self.graph[s][i][0], self.graph[s][i][1], self.graph[s][i][2]
            if self.level[v] != self.level[s] + 1 or cap == 0:
                i += 1
                continue
            reduced = self.dfs(v, t, min(f - ans, cap), ptr)
            if reduced:
                self.graph[s][i][1] -= reduced
                self.graph[v][rev][1] += reduced
                ans += reduced
                i += 1
        ptr[s] = i
        return ans

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow


