        """Convert literal to node index"""
        x = abs(lit) - 1  # Convert 1-indexed to 0-indexed
        if lit > 0:
            return x      # x_i is at node i
        else:
            return x + m  # ¬x_i is at node i+m

    # For each clause, add implications: ¬l1 → l2, ¬l2 → l1, etc.
    # This ensures at least one literal in the clause is true
    for clause in clauses:
        k = len(clause)
        for i in range(k):
            for j in range(k):
                if i == j:
                    continue

                l1 = clause[i]
                l2 = clause[j]

                # Add edge: if l1 is false, then l2 must be true (¬l1 → l2)
                u = get_idx(l1)
                v = get_idx(l2)
                adj[u + m].append(v)

    # Tarjan's algorithm for SCC
    id = [-1] * (2 * m)
    low = [0] * (2 * m)
    stack = []
    on_stack = [False] * (2 * m)
    scc = [-1] * (2 * m)
    scc_id = [0] * (2 * m)
    scc_count = 0
    timer = 0

    def tarjan(u):
        nonlocal timer, scc_count
        id[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
