    for i in range(n):
        l, r = map(int, lines[i + 1].split())
        ranges.append((i + 1, l, r))

    # Union-Find to find connected components (overlapping ranges)
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Connect overlapping ranges
    for i in range(n):
        for j in range(i + 1, n):
            r1, r2 = ranges[i], ranges[j]
            # Check if ranges overlap
            if max(r1[1], r2[1]) <= min(r1[2], r2[2]):
                union(r1[0], r2[0])

    # Group sheep by component
    components = {}
    for sheep in range(1, n + 1):
        comp = find(sheep)
        if comp not in components:
            components[comp] = []
        components[comp].append(sheep)

    # Sort each component by left endpoint (keeps overlapping ranges close)
    result = []
    for _, sheep_list in components.items():
        sheep_list.sort(key=lambda x: ranges[x-1][1])
        result.extend(sheep_list)

    return ' '.join(map(str, result)) + '\n'

