import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])

    if n == 0:
        # No visitors, can arrive exactly when opening
        return str(ts)

    arrivals = list(map(int, lines[2].split()))

    # Find the optimal time to arrive
    # Strategy: Arrive when receptionist becomes free and there's a gap before next visitor

    # Calculate when each existing visitor would be served
    current_time = ts

    for i in range(n):
        # Service starts when this person arrives (or after previous service finishes)
        service_start = max(current_time, arrivals[i])
        service_finish = service_start + t

        # Current person i is the last one we're checking
        # Check if there's a gap before next visitor (or if i is last visitor)
        if i == n - 1:
            # Last person, no next visitor to worry about
            # This would be the gap after last service
            best_arrival = service_finish
        else:
            # Check gap before next visitor
            if service_finish < arrivals[i + 1]:
                # There's a gap!
                if service_finish < tf:
                    best_arrival = service_finish
                    break
            current_time = service_finish
        current_time = service_finish

    # If we didn't find a gap, use default strategy
    # Try a strategy based on when queue empties

    # Calculate all service times
    service_times = []
    for i in range(n):
        if i == 0:
            service_finish = max(ts, arrivals[i]) + t
        else:
            service_finish = max(service_times[i-1], arrivals[i]) + t
        service_times.append(service_finish)

    # Find the best arrival time
    # If there's a gap, arrive at service_finish
    # Otherwise, arrive before some visitor to minimize queue

    # Strategy: Find the earliest service that allows gap
    for i in range(n):
        if i == 0:
            service_finish = ts + t
        else:
            service_finish = max(service_times[i-1], arrivals[i]) + t

        # Check if we can arrive right after this service finishes
        # and gets served before next visitor
        if i < n - 1:
            next_visit = arrivals[i + 1]
            if service_finish < next_visit and service_finish < tf:
                return str(service_finish)
        else:
            # Last visitor, can always arrive before them
            if service_finish < tf:
                return str(arrivals[i])

    # Default: arrive when reception opens
    return str(ts)

