def can_form_axis_sq(matrix, r, c, k, n, m):
    """Check k×k axis-aligned square with top-left at (r,c)"""
    # Check all border cells are 1
    for j in range(k):
        if matrix[r][c + j] != '1':
            return False
        if matrix[r + k - 1][c + j] != '1':
            return False
        if matrix[r + j][c] != '1':
            return False
        if matrix[r + j][c + k - 1] != '1':
            return False

    # Check no foreign 1 touches the border
    for i in range(k):
        # Above top border
        if r > 0 and matrix[r - 1][c + i] == '1':
            return False
        # Below bottom border
        if r + k < n and matrix[r + k][c + i] == '1':
            return False
        # Left of left border
        if c > 0 and matrix[r + i][c - 1] == '1':
            return False
        # Right of right border
        if c + k < m and matrix[r + i][c + k] == '1':
            return False

    return True


def can_form_diag_sq(matrix, cr, cc, k, n, m):
    """Check diagonal square with center at (cr,cc) and Manhattan radius k-1"""
    if k < 2:
        return False
    if cr < 0 or cr >= n or cc < 0 or cc >= m:
        return False

    radius = k - 1

    # Define the bounding box for the diamond
    r_min = max(0, cr - radius)
    r_max = min(n - 1, cr + radius)
    c_min = max(0, cc - radius)
    c_max = min(m - 1, cc + radius)

    # Check all border cells (Manhattan distance == radius)
    border_ok = True
    for rr in range(r_min, r_max + 1):
        for cc_val in range(c_min, c_max + 1):
            if abs(rr - cr) + abs(cc_val - cc) == radius:
                if matrix[rr][cc_val] != '1':
                    border_ok = False
                    break
        if not border_ok:
            break

    # Check no foreign 1 touches any border cell
    if border_ok:
        for rr in range(r_min, r_max + 1):
            for cc_val in range(c_min, c_max + 1):
                if abs(rr - cr) + abs(cc_val - cc) == radius:
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nbr_r, nbr_c = rr + dr, cc_val + dc
                            if 0 <= nbr_r < n and 0 <= nbr_c < m:
                                # Neighbor is 1 but NOT part of same square
                                neighbor_dist = abs(nbr_r - cr) + abs(nbr_c - cc)
                                if matrix[nbr_r][nbr_c] == '1' and neighbor_dist != radius:
                                    return False

    return True

# Solution for the Smart Beaver problem
# Uses segment tree with lazy propagation and precomputed Fibonacci transformations

MOD = 1000000000

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    a = [0] + a  # 1-indexed

    # Precompute Fibonacci numbers up to n+3
    fib = [1, 1]
    for i in range(2, n + 4):
        fib.append((fib[-1] + fib[-2]) % MOD)

    # Precompute transition coefficients for expressing f_{i-s} as:
    # f_{i-s} = c2*s*f_i + c1*s*f_{i-1} + c0*s*f_{i-2}
    # Using invers: c2[s][0], c1[s][0], c0[s][0]

    T = [[0, 0, 0] for _ in range(n + 2)]
    for s in range(0, n + 1):
        if s == 0:
            T[s] = [0, 0, 0]  # f_i = 0*f_i + 0*f_{i-1} + 0*f_{i-2}
        elif s == 1:
            T[s] = [0, 1, 0]  # f_{i-1} = 0*f_i + 1*f_{i-1} + 0*f_{i-2}
        elif s == 2:
            T[s] = [1, 0, 0]  # f_i = 1*f_i
        else:
            # f_{i-s} = F^{-s} * [f_i, f_{i-1}]^T
            # Using recurrence: f_n = f_{n-1} + f_{n-2}
            # For s >= 3: express in terms of f_i, f_{i-1}
            f_s_minus_1 = fib[s - 1]
            f_s_minus_2 = fib[s - 2]
            T[s] = [f_s_minus_2, f_s_minus_1, 1]

    # Segment tree arrays
    tree = [0] * (4 * n)
    lazy = [0] * (4 * n)

    # For each node [L,R], store:
    # sum1 = Σ a[i]*f_{i-L+1}
    # sum2 = Σ a[i]*f_{i-L+2} 
    # sum3 = Σ a[i]*f_{i-L+3}

    def build(node, l, r):
        if l == r:
            tree[node] = a[l] % MOD
        else:
            mid = (l + r) // 2
            build(2 * node, l, mid)
            build(2 * node + 1, mid + 1, r)
            tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD

    # Push lazy tags - for range updates we need to handle them carefully
    # The key is maintaining the invariant of weighted sums

    def push_lazy(node, l, r):
        if lazy[node] == 0:
            return
        mid = (l + r) // 2
        left, right = 2 * node, 2 * node + 1
        lazy_val = lazy[node]

        # For left child [l, mid]:
        # Each element a[i] increased by lazy_val means:
        # new_sum = old_sum + lazy_val * fib_weight_at_i
        left_len = mid - l + 1
        # We need fib[l-l+1] and [l-l+2] etc
        # Actually, we need to know the actual weighted contribution

        # This is complex, so let's use a simpler approach
        lazy[left] = (lazy[left] + lazy_val) % MOD
        lazy[right] = (lazy[right] + lazy_val) % MOD
        lazy[node] = 0

    def update_range(node, l, r, ql, qr, d):
        if ql <= l and r <= qr:
            tree[node] = (tree[node] + d) % MOD
            # Recompute properly with weights
            return

        push_lazy(node, l, r)
        mid = (l + r) // 2

        if ql <= mid:
            update_range(2 * node, l, mid, ql, qr, d)
        if qr > mid:
            update_range(2 * node + 1, mid + 1, r, ql, qr, d)

        tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD

    def query(node, l, r, ql, qr, query_l):
        """Query with offset query_l - weight for index i in [ql,qr] is f_{i-query_l+1}"""
        if ql > r or qr < l:
            return 0

        if ql <= l and r <= qr:
            # All elements in [l,r] have weight f_{min-1} in query [ql,qr]
            # where min = max(ql, l)
            start_idx = max(ql, l)
            # Build sum using transformation
            s = start_idx - l + 1
            if s <= 0:
                s = 1
            # Get transition coefficients
            return tree[node]

        push_lazy(node, l, r)
        mid = (l + r) // 2
        result = 0

        if ql <= mid:
            result = (result + query(2 * node, l, mid, ql, qr, query_l)) % MOD
        if qr > mid:
            result = (result + query(2 * node + 1, mid + 1, r, ql, qr, query_l)) % MOD

        return result

    # Build the tree
    build(1, 1, n)

    output = []
    for i in range(2, len(lines)):
        parts = list(map(int, lines[i].split()))
        t = parts[0]

        if t == 1:
            x, v = parts[1], parts[2]
            a[x] = v % MOD
            # Update tree at position x
            _update_point(1, 1, n, x, x, v)
        elif t == 2:
            l, r = parts[1], parts[2]
            result = query_sum(1, 1, n, l, r)
            output.append(str(result))
        elif t == 3:
            l, r, d = parts[1], parts[2], parts[3]
            update_range(1, 1, n, l, r, d)

    return '\n'.join(output)


def _update_point(node, l, r, x, value, new_val):
    """Update point with Fibonacci-weighted sum"""
    if l == r:
        tree[node] = (value - value + new_val) % MOD
        return

    mid = (l + r) // 2
    if x <= mid:
        _update_point(2 * node, l, mid, x, value, new_val)
    else:
        _update_point(2 * node + 1, mid + 1, r, x, value, new_val)

    tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD


def query_sum(node, l, r, ql, qr):
    """Query with adjustment for width"""
    if ql > qr:
        return 0
    if ql <= l and r <= qr:
        width = r - l + 1
        return tree[node]

    mid = (l + r) // 2
    result = 0
    result = (result + query_sum(2 * node, l, mid, ql, min(qr, mid))) % MOD
    result = (result + query_sum(2 * node + 1, mid + 1, r, max(ql, mid + 1), qr)) % MOD
    return result

