def solution(s):
    """
    Calculate minimum cost to make array elements have GCD > 1.
    """
    if not s:
        return ''

    parts = s.split()
    n = int(parts[0])
    a = int(parts[1])
    b = int(parts[2])
    arr = list(map(int, parts[3:3 + n]))

    if n == 0:
        return '0'

    def get_prime_factors(num):
        """Get all prime factors of num"""
        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return factors

    # Collect all unique prime factors from the array
    candidate_divs = set()
    for x in arr:
        candidate_divs.update(get_prime_factors(x))

    min_cost = float('inf')

    for d in candidate_divs:
        if d == 1:
            continue

        # Calculate cost to make element divisible by d (or infinity if impossible)
        costs = []
        for x in arr:
            rem = x % d
            if rem == 0 or rem == 1 or rem == d - 1:
                costs.append(b)
            else:
                costs.append(float('inf'))

        # Skip if any element cannot be fixed (must be removed instead)
        if any(c == float('inf') for c in costs):
            continue

        # Build prefix sum array for efficient range cost calculation
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + costs[i]

        # Option 1: No removal - fix all elements
        base_cost = prefix[n]
        if base_cost < min_cost:
            min_cost = base_cost

        # Option 2: Remove one subsegment [i, j]
        # Keep prefix [0, i-1] and suffix [j+1, n-1]
        for i in range(n):
            for j in range(i, n):
                # Cannot remove entire array
                if j - i + 1 >= n:
                    continue

                # Cost of keeping elements outside removal segment
                keep_cost = prefix[i] + (prefix[n] - prefix[j + 1])

                # Removal cost
                removal_cost = a * (j - i + 1)

                total = keep_cost + removal_cost
                if total < min_cost:
                    min_cost = total

    return str(min_cost)

