def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if not lines or idx >= len(lines):
        return ''

    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        wires = []
        for i in range(n):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            wires.append((x, y))

        if n <= 1:
            results.append('0')
            continue

        # DSU to find connected components of contacts
        parent = {}
        def find(x):
            if x not in parent:
                parent[x] = x
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[rx] = ry

        # Union contacts for each wire - wires sharing contacts get connected
        for x, y in wires:
            union(x, y)

        # Find which component each wire belongs to
        wire_components = [find(wires[i][0]) for i in range(n)]

        # Count number of components
        num_components = len(set(wire_components)) - 1

        if num_components <= 0:
            results.append('0')
        else:
            # We need num_components operations (connecting them to form a tree)
            # Find common contact - use first contact of first wire (based on indexing)
            first_idx = min(range(n), key=lambda i: wire_components[i])
            common_contact = wires[first_idx][0]

            # Group wires by component
            comps = {}
            for i, root in enumerate(wire_components):
                if root not in comps:
                    comps[root] = []
                comps[root].append(i)

            # Pick the first component as the "base"
            base_root = wire_components[first_idx]

            # Collect contacts from the base component
            base_contacts = set()
            for i in comps[base_root]:
                base_contacts.add(wires[i][0])
                base_contacts.add(wires[i][1])

            sorted_roots = sorted(comps.keys())
            ops = []

            for root in sorted_roots:
                if root == base_root:
                    continue

                # Take first wire from this component
                wire_idx = comps[root][0]
                x, y = wires[wire_idx]

                # Change the smaller contact to common_contact
                smaller = min(x, y)
                ops.append(f"{wire_idx + 1} {smaller} {common_contact}")

            results.append(str(len(sorted_roots) - 1))
            results.extend(ops)

    return '\n'.join(results)

def solution(input_data):
