    return ''.join(results)

def analyze_round(s, e):
    """Analyze a single round - return (can_force_win, can_force_lose) for the current player"""

    @lru_cache(maxsize=1000000)
    def can_force_win(player_turn, current_val):
        """Can current player force a win from (player_turn, current_val)?"""

        # Check if current value exceeds e (shouldn't happen in normal play)
        if current_val > e:
            return False

        # Count moves available
        moves = e - current_val + 1

        # If only +1 is possible (2*current_val > e)
        if 2 * current_val > e:
            # With only +1 moves, parity determines winner
            # (e - current_val + 1) is the number of +1 moves needed
            if (e - current_val + 1) % 2 == 0:
                return True  # Current player wins
            else:
                return False  # Current player loses

        # Both options available, check both paths
        # Option 1: add 1
        if can_force_win(1 - player_turn, current_val + 1)[0]:
            return True
        # Option 2: double
        if can_force_win(1 - player_turn, 2 * current_val)[0]:
            return True

        return False

    @lru_cache(maxsize=1000000)
    def must_lose(player_turn, current_val):
        """Must current player lose (no matter what they choose)?"""

        if current_val > e:
            return True

        # If only +1 is possible
        if 2 * current_val > e:
            if (e - current_val + 1) % 2 == 1:
                return True
            else:
                return False

        # Both options available - must lose if all choices lead to loss
        if must_lose(1 - player_turn, current_val + 1)[1] and must_lose(1 - player_turn, 2 * current_val)[1]:
            return True

        return False

    return can_force_win(1, s), must_lose(1, s)

