    def valid_set(a, b, is_final):
        """Check if (a:b) is a valid set score, team a won."""
        min_p = 15 if is_final else 25
        if a == b:
            return False
        # Winner must have min points and lead by 2
        if a < min_p or b < min_p - 1:
            return False
        if a - b < 2:
            return False
        return True

    def find_one_pattern(a, b, wins_a, wins_b):
        """Find one valid set distribution for match score wins_a:stars:**"""
        n = wins_a + wins_b  # number of sets
        if n < 3 or n > 5:
            return None

        # Backtracking: assign scores to each set
        best = [None]

        def backtrack(rem_a, rem_b, sa, sb, sets, final_turn):
            if sa == wins_a and sb == wins_b:
                if len(sets) == n and rem_a == 0 and rem_b == 0:
                    best[0] = sets[:]
                    return True
                return False

            if len(sets) >= n:
                return False

            # Determine min points for this set
            is_this_final = (final_turn)

            # Try team A winning this set
            min_a = 25 if not is_this_final else 15
            for a_s in range(min_a, rem_a + 1):
                # B can have up to 2 fewer points (deuce continues)
                max_b = min(b, a_s - 2) if a_s > min_a else min(b, 24)
                max_b = min(max_b, rem_b)

                for b_s in range(min(0, max_b) + 1):
                    if a_s > b_s and a_s >= min_a and a_s - b_s >= 2:
                        left_a, left_b = rem_a - a_s, rem_b - b_s
                        if backtrack(left_a, left_b, sa + 1, sb, 
                                   sets + [(a_s, b_s)], False):
                            return True

            # Try team B winning this set
            min_b = 25 if not is_this_final else 15
            for b_s in range(min_b, rem_b + 1):
                max_a = min(a, b_s - 2) if b_s > min_b else min(a, 24)
                max_a = min(max_a, rem_a)

                for a_s in range(min(0, max_a) + 1):
                    if b_s > a_s and b_s >= min_b and b_s - a_s >= 2:
                        left_a, left_b = rem_a - a_s, rem_b - b_s
                        if backtrack(left_a, left_b, sa, sb + 1,
                                   sets + [(a_s, b_s)], False):
                            return True

            return False

        if backtrack(a, b, 0, 0, [], True):
            return best[0]
        return None

    def solve_one(a, b):
        # Try scores in order: 3:0 > 3:1 > 3:2 > 0:3 > 1:3 > 2:3
        for wa, wb in [(3,0),(3,1),(3,2),(0,3),(1,3),(2,3)]:
