def solution(s):
    import sys
    sys.setrecursionlimit(200000)

    try:
        parts = s.strip().split()
        if len(parts) != 3:
            return "0"
        n, k, m = map(int, parts)
    except:
        return "0"

    # Special case: k=1, we can start at any planet (n choices)
    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_paths(last, visited_tuple):
        """
        last: the last planet we visited
        visited_tuple: sorted tuple of visited planets (including last)
        """
        if len(visited_tuple) == k:
            return 1

        count = 0
        # Can move to any planet y where 1 <= y <= last + m
        limit = min(n, last + m)
        for nxt in range(1, limit + 1):
            if nxt not in visited_tuple:
                count = (count + count_paths(nxt, visited_tuple + (nxt,)))
                if count >= MOD:
                    count %= MOD
        return count % MOD

    total = 0
    for start in range(1, n + 1):
        total = (total + count_paths(start, (start,)))
        if total >= MOD:
            total %= MOD

    return str(total)

import sys
from collections import deque

def solution(s):
    # Try to work efficiently for all inputs
    n_str = s.strip()
    n = int(n_str)

    if n == 0:
        return '0\n'

    # Use memoization with iterative DP to avoid recursion limits
    # For BFS-style shortest path
    memo = {}

    def get_digits(val):
        """Get unique digits present in the number"""
        return set(str(val))

    def bfs_solve(start):
        """BFS to find minimum operations"""
        from collections import deque

        queue = deque([(start, 0)])
        visited = {start}
        memo[start] = 0

        while queue:
            current, ops = queue.popleft()

            if current == 0:
                return ops

            # Get all unique digits in current number
            digits = get_digits(current)

            # Try all possible subtractions
            for d in digits:
                next_val = current - d
                if next_val not in visited:
                    visited.add(next_val)
                    memo[next_val] = ops + 1
                    queue.append((next_val, ops + 1))

        return memo.get(start, 0)

    # For very large n, we may need a different approach
    if n > 10**12:
        # Use greedy heuristic for very large numbers
        # Subtract largest digit at each step
        def greedy_solve(val):
            count = 0
            while val > 0:
                if val <= 1:
                    count += 1
                    break
                d = int(str(val)[::-1][::-1])  # Get first digit
                # Actually get the max digit
                max_d = 0
                for c in str(val):
                    d = int(c)
                    if d > max_d:
                        max_d = d
                val -= max_d
                count += 1
            return count

        return f'{greedy_solve(n)}\n'
    else:
        return f'{bfs_solve(n)}\n'

